        // MOVE EIBTASKN TO WS-TASKNUM
        Cobol.move(f260_EIBTASKN, f5_WS_TASKNUM, CS);
        // MOVE EIBCALEN TO WS-CALEN
        Cobol.move(f264_EIBCALEN, f8_WS_CALEN, CS);
        // INITIALIZE DB2-IN-INTEGERS
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 0, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 4, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 8, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 12, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 14, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 18, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 22, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 24, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 28, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 32, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 34, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 38, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 42, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 44, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 48, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 50, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 54, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 56, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 60, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 62, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 66, 4, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 68, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 72, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 76, 9, 0, true, false), CS);
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f119_DB2_IN_INTEGERS.storage(), f119_DB2_IN_INTEGERS.offset() + 80, 9, 0, true, false), CS);
        // INITIALIZE DB2-OUT-INTEGERS
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(f145_DB2_OUT_INTEGERS.storage(), f145_DB2_OUT_INTEGERS.offset() + 0, 9, 0, true, false), CS);
        // IF EIBCALEN IS EQUAL TO ZERO
        if (Cobol.num(f264_EIBCALEN, CS).compareTo(BigDecimal.ZERO) == 0) {
            // MOVE ' NO COMMAREA RECEIVED' TO EM-VARIABLE
            Cobol.move(" NO COMMAREA RECEIVED", f17_EM_VARIABLE, CS);
            // PERFORM WRITE-ERROR-MESSAGE
            perform(7, 7);
            // EXEC CICS ABEND ABCODE('LGCA') NODUMP END-EXEC
            String exit1 = task.abend("LGCA".strip());
            if (exit1 == null) throw abended();
            if (true) return GOTO | paragraph(exit1);
        }
        // MOVE '00' TO CA-RETURN-CODE
        Cobol.move("00", f172_CA_RETURN_CODE, CS);
        // SET WS-ADDR-DFHCOMMAREA TO ADDRESS OF DFHCOMMAREA
        // the pointer is never read (write_only_pointers): no effect any output can show
        // MOVE CA-CUSTOMER-NUM TO DB2-CUSTOMERNUM-INT
        Cobol.move(f173_CA_CUSTOMER_NUM, f120_DB2_CUSTOMERNUM_INT, CS);
        // MOVE ZERO TO DB2-C-PolicyNum-INT
        Cobol.moveFigurative(Figurative.ZEROS, f141_DB2_C_POLICYNUM_INT, CS);
        // MOVE CA-CUSTOMER-NUM TO EM-CUSNUM
        Cobol.move(f173_CA_CUSTOMER_NUM, f19_EM_CUSNUM, CS);
        // ADD WS-CA-HEADER-LEN TO WS-REQUIRED-CA-LEN
        BigDecimal t2 = BigDecimal.valueOf(f29_WS_CA_HEADER_LEN);
        f30_WS_REQUIRED_CA_LEN = Cobol.zoned(f30_WS_REQUIRED_CA_LEN.add(t2), 4, 0, true, false, CS);
        // EVALUATE CA-REQUEST-ID
        if ((Cobol.compare(f171_CA_REQUEST_ID, "01AEND", CS) == 0)) {
            // ADD WS-FULL-ENDOW-LEN TO WS-REQUIRED-CA-LEN
            BigDecimal t4 = BigDecimal.valueOf(f42_WS_FULL_ENDOW_LEN);
            f30_WS_REQUIRED_CA_LEN = Cobol.zoned(f30_WS_REQUIRED_CA_LEN.add(t4), 4, 0, true, false, CS);
            // MOVE 'E' TO DB2-POLICYTYPE
            Cobol.move("E", f59_DB2_POLICYTYPE, CS);
        } else if ((Cobol.compare(f171_CA_REQUEST_ID, "01AHOU", CS) == 0)) {
            // ADD WS-FULL-HOUSE-LEN TO WS-REQUIRED-CA-LEN
            BigDecimal t6 = BigDecimal.valueOf(f43_WS_FULL_HOUSE_LEN);
            f30_WS_REQUIRED_CA_LEN = Cobol.zoned(f30_WS_REQUIRED_CA_LEN.add(t6), 4, 0, true, false, CS);
            // MOVE 'H' TO DB2-POLICYTYPE
            Cobol.move("H", f59_DB2_POLICYTYPE, CS);
        } else if ((Cobol.compare(f171_CA_REQUEST_ID, "01AMOT", CS) == 0)) {
            // ADD WS-FULL-MOTOR-LEN TO WS-REQUIRED-CA-LEN
            BigDecimal t8 = BigDecimal.valueOf(f44_WS_FULL_MOTOR_LEN);
            f30_WS_REQUIRED_CA_LEN = Cobol.zoned(f30_WS_REQUIRED_CA_LEN.add(t8), 4, 0, true, false, CS);
            // MOVE 'M' TO DB2-POLICYTYPE
            Cobol.move("M", f59_DB2_POLICYTYPE, CS);
        } else if ((Cobol.compare(f171_CA_REQUEST_ID, "01ACOM", CS) == 0)) {
            // ADD WS-FULL-COMM-LEN TO WS-REQUIRED-CA-LEN
            BigDecimal t10 = BigDecimal.valueOf(f45_WS_FULL_COMM_LEN);
            f30_WS_REQUIRED_CA_LEN = Cobol.zoned(f30_WS_REQUIRED_CA_LEN.add(t10), 4, 0, true, false, CS);
            // MOVE 'C' TO DB2-POLICYTYPE
            Cobol.move("C", f59_DB2_POLICYTYPE, CS);
        } else if (true) {
            // MOVE '99' TO CA-RETURN-CODE
            Cobol.move("99", f172_CA_RETURN_CODE, CS);
            // EXEC CICS RETURN END-EXEC
            caBack.run();
            task.returnTransid(null, null);
            if (true) throw new Goback();
        }
        // IF EIBCALEN IS LESS THAN WS-REQUIRED-CA-LEN
        if (f30_WS_REQUIRED_CA_LEN.compareTo(Cobol.num(f264_EIBCALEN, CS)) > 0) {
            // MOVE '98' TO CA-RETURN-CODE
            Cobol.move("98", f172_CA_RETURN_CODE, CS);
            // EXEC CICS RETURN END-EXEC
            caBack.run();
            task.returnTransid(null, null);
            if (true) throw new Goback();
        }
        // PERFORM INSERT-POLICY
        perform(2, 2);
        // EVALUATE CA-REQUEST-ID
        if ((Cobol.compare(f171_CA_REQUEST_ID, "01AEND", CS) == 0)) {
            // PERFORM INSERT-ENDOW
            perform(3, 3);
        } else if ((Cobol.compare(f171_CA_REQUEST_ID, "01AHOU", CS) == 0)) {
            // PERFORM INSERT-HOUSE
            perform(4, 4);
        } else if ((Cobol.compare(f171_CA_REQUEST_ID, "01AMOT", CS) == 0)) {
            // PERFORM INSERT-MOTOR
            perform(5, 5);
        } else if ((Cobol.compare(f171_CA_REQUEST_ID, "01ACOM", CS) == 0)) {
            // PERFORM INSERT-COMMERCIAL
            perform(6, 6);
        } else if (true) {
            // MOVE '99' TO CA-RETURN-CODE
            Cobol.move("99", f172_CA_RETURN_CODE, CS);
        }
        // EXEC CICS Link Program(LGAPVS01) Commarea(DFHCOMMAREA) LENGTH(32500) END-EXEC
        Storage cw14 = Cobol.commarea(f170_DFHCOMMAREA, 32500);
        Lgapvs01Dfhcommarea ca13 = out_Lgapvs01Dfhcommarea(cw14, 0);
        String lr12 = task.link(f147_LGAPVS01.strip(), ca13, 32500, cw14.bytes);
        if ("NORMAL".equals(lr12)) {
            if (!task.linkAreaBack()) { in_Lgapvs01Dfhcommarea(ca13, cw14, 0); }
            Cobol.commareaBack(cw14, f170_DFHCOMMAREA);
        }
        String exit15 = task.abendExit();
        if (exit15 != null) return GOTO | paragraph(exit15);
